SourceCode.Declaration:
/// <summary>
/// Activates or deactivates a device's fleet row.
///
/// That specific device can still sign in either way - see the field help on
/// HSMobileOpsDevice.IsActive. This is not a remote kill switch on the device itself; a lost or
/// stolen handheld needs its worker accounts locked and the client secret rotated, neither of
/// which lives on this table. It does, however, now feed HSMobileOpsLicense's device-count check
/// - deactivating a retired handheld frees the license slot it was holding for a replacement.
/// </summary>
class HSMobileOpsToggleDeviceActive
{

}

Method.Source:
public static void main(Args _args)
{
    HSMobileOpsDevice device;
    boolean           makeActive;

    if (!_args || !_args.record() || _args.dataset() != tableNum(HSMobileOpsDevice))
    {
        throw error('Select a device first');
    }

    device     = _args.record() as HSMobileOpsDevice;
    makeActive = device.IsActive != NoYes::Yes;

    ttsbegin;
    device.selectForUpdate(true);
    device.IsActive = makeActive ? NoYes::Yes : NoYes::No;
    device.update();
    ttscommit;

    info(strFmt('%1 is now %2', device.FriendlyName, makeActive ? 'active' : 'inactive'));
}
